import { IsBoolean, IsInt, IsOptional, Matches, Min } from 'class-validator';

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

export class SubmitDraftsDto {
  @IsOptional() @Matches(DATE_ONLY, { message: 'from must be YYYY-MM-DD' })
  from?: string;

  @IsOptional() @Matches(DATE_ONLY, { message: 'to must be YYYY-MM-DD' })
  to?: string;

  // Submit only the drafts generated by one recurring schedule
  @IsOptional() @IsInt() @Min(1)
  scheduleId?: number;

  // true = preview what would be submitted, without changing anything
  @IsOptional() @IsBoolean()
  dryRun?: boolean;
}
